INSERT INTO _migration_490_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igbio_nutrition_s2_001', 'topic_igcse_bio_nutrition', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Which gas do plants take in for photosynthesis?', 'multiple_choice', NULL, '["A. Carbon dioxide","B. Oxygen","C. Nitrogen","D. Hydrogen"]', 'A', 'During photosynthesis plants take in carbon dioxide and water and, using light energy trapped by chlorophyll, produce glucose and oxygen. Oxygen is a product rather than a reactant, and nitrogen and hydrogen gases play no direct part in the process. Therefore the correct answer is A: Carbon dioxide.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Recall', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igbio_nutrition_s2_002', 'topic_igcse_bio_nutrition', 'subj_igcse_biology', 'igcse', NULL, NULL, 'In which part of a leaf does most photosynthesis take place?', 'multiple_choice', NULL, '["A. Lower epidermis","B. Palisade mesophyll cells","C. Guard cells","D. Spongy mesophyll air spaces"]', 'B', 'Palisade mesophyll cells lie near the upper surface of the leaf, are packed with chloroplasts and receive the most light, so they carry out most photosynthesis. The lower epidermis contains few chloroplasts, guard cells mainly control the stomatal pore, and the air spaces allow gases to circulate rather than photosynthesise. Therefore the correct answer is B: Palisade mesophyll cells.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igbio_nutrition_s2_003', 'topic_igcse_bio_nutrition', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Which organ produces saliva containing amylase to begin the digestion of starch?', 'multiple_choice', NULL, '["A. Stomach","B. Liver","C. Salivary glands","D. Large intestine"]', 'C', 'The salivary glands secrete saliva containing salivary amylase, which starts breaking starch down into maltose in the mouth. The stomach digests protein with pepsin, the liver makes bile, and the large intestine absorbs water; none of these organs secretes amylase. Therefore the correct answer is C: Salivary glands.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igbio_nutrition_s2_004', 'topic_igcse_bio_nutrition', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Which nutrient group is the main source of energy in the human diet?', 'multiple_choice', NULL, '["A. Vitamins","B. Mineral ions","C. Fibre (roughage)","D. Carbohydrates"]', 'D', 'Carbohydrates such as starch and sugars are broken down to glucose, which is respired to release energy, making them the main energy source in the diet. Vitamins and mineral ions are needed in small amounts to keep tissues healthy, and fibre cannot be digested and only aids peristalsis. Therefore the correct answer is D: Carbohydrates.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Recall', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igbio_nutrition_s2_005', 'topic_igcse_bio_nutrition', 'subj_igcse_biology', 'igcse', NULL, NULL, 'A pondweed is exposed to increasing light intensity while carbon dioxide concentration and temperature are kept constant. What happens to the rate of photosynthesis?', 'multiple_choice', NULL, '["A. It increases and then levels off","B. It increases without limit","C. It stays exactly the same","D. It decreases steadily"]', 'A', 'Light is the limiting factor at first, so the rate rises as light intensity increases, but once another factor such as carbon dioxide concentration becomes limiting, the rate levels off. The rate cannot rise forever while other factors are fixed, cannot stay unchanged while light is limiting, and does not fall when more light becomes available. Therefore the correct answer is A: It increases and then levels off.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Apply', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igbio_nutrition_s2_006', 'topic_igcse_bio_nutrition', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Which vessels transport dissolved sugars from the leaves to the rest of the plant?', 'multiple_choice', NULL, '["A. Xylem","B. Phloem","C. Root hair cells","D. Guard cells"]', 'B', 'The phloem transports sucrose and amino acids from sources such as the leaves to sinks such as roots and fruits by translocation. Xylem carries water and mineral ions upwards, root hair cells absorb water from the soil, and guard cells open and close stomata; none of these transports sugar. Therefore the correct answer is B: Phloem.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge');
INSERT INTO _migration_490_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_490_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_490_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'igcse-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Biology (0610) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-biology-0610/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_490_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'igcse-bio-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Biology (0610) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-biology-0610/', 0, 1 FROM _migration_490_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_490_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_490_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_490_expected e ON e.id = r.question_id WHERE r.batch_id IS 'igcse-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Biology (0610) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-biology-0610/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_490_expected e ON e.id = q.id) = 6 THEN 1 ELSE 0 END;
